import {places,suspects,judge,ending} from './case.js';
const $=s=>document.querySelector(s), canvas=$('#world'),ctx=canvas.getContext('2d'),modal=$('#modal'),content=$('#content');
let W=innerWidth,H=innerHeight,yaw=0,player={x:0,z:-21},nearest=null,last=0,elapsed=0,attempts=0,solved=false;
const keys=new Set(),found=new Set(),faces=[];
const labels=places.map(p=>{let el=document.createElement('div');el.className='label';el.textContent=p.name;$('#labels').append(el);return el});
function resize(){W=innerWidth;H=innerHeight;const d=Math.min(devicePixelRatio||1,2);canvas.width=W*d;canvas.height=H*d;ctx.setTransform(d,0,0,d,0,0)}addEventListener('resize',resize);resize();
function show(html){keys.clear();content.innerHTML=html;if(!modal.open)modal.showModal();content.scrollTop=0;modal.scrollTop=0}
$('#close').onclick=()=>modal.close();modal.addEventListener('close',()=>keys.clear());
function help(){show('<small>霧鐘町へようこそ</small><h2>五人の証言から、真相へ。</h2><p>今日14時、町長が姿を消した。秘書は「町を出た」と説明している。しかし、町には食い違う証言が残っている。</p><p>五つの建物に近づき「調べる」を押して、住民の証言と証拠を集めよう。建物には入らず、入口付近で調査できる。</p><p><b>WASD・矢印</b>で移動、<b>Q・R</b>で視点を回転、<b>E</b>で調査。画面右下のボタンでも操作できる。</p><p>証拠は捜査手帳で再確認できる。五つ集めたら「事件を解く」で人物・場所・直接の根拠二つを選ぼう。間違えても再挑戦できる。</p><p>進行はこのページを開いている間だけ保持される。音声・AIへの接続は不要。</p>')}
$('#help').onclick=help;
function inspect(){if(!nearest||modal.open)return;found.add(nearest.id);$('#count').textContent=`証拠 ${found.size} / 5`;const p=nearest;show(`<small>聞き込み / ${p.name}</small><h2>${p.person}</h2><blockquote>「${p.quote}」</blockquote><div class="evidence"><small>捜査手帳に記録</small><h3>${p.title}</h3><p>${p.text}</p></div>`)}
$('#interact').onclick=inspect;
$('#notebook').onclick=()=>show(`<small>CASE NOTES / ${found.size}件</small><h2>捜査手帳</h2>${found.size?places.filter(p=>found.has(p.id)).map(p=>`<section class="evidence"><h3>${p.name} — ${p.person}</h3><blockquote>「${p.quote}」</blockquote><b>${p.title}</b><p>${p.text}</p></section>`).join(''):'<p>まだ証拠はない。まずは建物に近づいて聞き込みをしよう。</p>'}`);
function solve(){if(found.size<5){show(`<h2>まだ調査できる場所がある</h2><p>残り${5-found.size}か所で証言と証拠を集めよう。</p><p>${places.filter(p=>!found.has(p.id)).map(p=>p.name).join(' / ')}</p>`);return}show(`<small>FINAL DEDUCTION</small><h2>あなたの推理を聞かせて。</h2><form id="answer"><label for="suspect">町長を閉じ込めた人物</label><select id="suspect" required><option value="">選んでください</option>${suspects.map(x=>`<option>${x}</option>`).join('')}</select><label for="location">町長がいる場所</label><select id="location" required><option value="">選んでください</option>${['役場の資料室','喫茶店の地下','隣町の郵便局'].map(x=>`<option>${x}</option>`).join('')}</select><p>「本人が施錠したこと」と「直前に町長がそこにいたこと」を直接示す証拠を二つ選ぼう。</p>${places.map(p=>`<label class="choice"><input type="checkbox" name="ev" value="${p.id}">${p.title}</label>`).join('')}<p id="feedback" role="status"></p><button type="submit">推理を確定する</button></form>`);$('#answer').onsubmit=e=>{e.preventDefault();const ev=[...content.querySelectorAll('input:checked')].map(x=>x.value);if(ev.length!==2){$('#feedback').textContent='根拠は二つ選んでください。';return}attempts++;if(judge($('#suspect').value,$('#location').value,ev)){solved=true;show(`<small>CASE CLOSED</small><h2>町長は、町の中にいた。</h2><p>${ending}</p><div class="evidence"><h3>時計がついた、もう一つの嘘</h3><p>14:05の目撃は、進んだ時計によるもの。本当は13:55だった。目撃者が嘘をついているとは限らない。</p></div><p>証拠 5 / 5 ・解答 ${attempts}回 ・調査 ${Math.max(1,Math.round(elapsed/60))}分</p><p>閉じると町に戻り、証拠を読み返せる。</p>`);$('#mission h2').textContent='事件解決 — 町長を保護';}else $('#feedback').textContent='その推理では証拠がつながらない。認証記録と、直前の町長の居場所を読み直してみよう。'}}
$('#solve').onclick=solve;
const valid=['w','a','s','d','q','r','arrowup','arrowdown','arrowleft','arrowright'];addEventListener('keydown',e=>{if(modal.open)return;let k=e.key.toLowerCase();if(valid.includes(k)){e.preventDefault();keys.add(k)}if(k==='e'&&!e.repeat)inspect()});addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));addEventListener('blur',()=>keys.clear());document.addEventListener('visibilitychange',()=>keys.clear());
for(const b of document.querySelectorAll('[data-key]')){b.onpointerdown=e=>{if(modal.open)return;e.preventDefault();b.setPointerCapture(e.pointerId);keys.add(b.dataset.key)};for(const ev of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(ev,()=>keys.delete(b.dataset.key))}
function blocked(x,z){return Math.abs(x)>27||Math.abs(z)>28||places.some(p=>Math.abs(x-p.x)<p.w/2+.55&&Math.abs(z-p.z)<p.d/2+.55)||Math.hypot(x,z)<2.1}
const pitch=.72;
function cameraPoint(v){let x=v[0]-player.x,z=v[2]-player.z;let right=x*Math.cos(yaw)-z*Math.sin(yaw);let forward=x*Math.sin(yaw)+z*Math.cos(yaw)+19;let dy=v[1]-18;return [right,dy*Math.cos(pitch)+forward*Math.sin(pitch),forward*Math.cos(pitch)-dy*Math.sin(pitch)]}
function screen(v){let [x,y,z]=cameraPoint(v),f=Math.min(W,H)*1.08;return [W/2+x*f/z,H*.48-y*f/z,z]}
function face(v,c){let dep=v.map(cameraPoint);if(dep.some(p=>p[2]<.4))return;faces.push({v:v.map(screen),z:dep.reduce((a,b)=>a+b[2],0)/v.length,c})}
function shade(c,m){return '#'+c.slice(1).match(/../g).map(s=>Math.round(parseInt(s,16)*m).toString(16).padStart(2,'0')).join('')}
function box(x,y,z,w,h,d,c){let a=[x-w/2,y,z-d/2],b=[x+w/2,y,z-d/2],cc=[x+w/2,y,z+d/2],dd=[x-w/2,y,z+d/2],up=p=>[p[0],p[1]+h,p[2]];face([a,b,up(b),up(a)],shade(c,.82));face([b,cc,up(cc),up(b)],shade(c,.67));face([cc,dd,up(dd),up(cc)],c);face([dd,a,up(a),up(dd)],shade(c,.9));face([up(a),up(b),up(cc),up(dd)],c)}
function roof(p){let {x,z,w,d,h}=p,a=[x-w/2-.5,h,z-d/2-.5],b=[x+w/2+.5,h,z-d/2-.5],c=[x+w/2+.5,h,z+d/2+.5],dd=[x-w/2-.5,h,z+d/2+.5],e=[x,h+2,z-d/2-.5],f=[x,h+2,z+d/2+.5];face([a,e,f,dd],p.roof);face([e,b,c,f],shade(p.roof,.7));face([a,b,e],p.color);face([dd,f,c],p.color)}
function tree(x,z,s=1){box(x,0,z,.4,2*s,.4,'#81715a');for(let k=0;k<2;k++){let y=(1.2+k*1.1)*s,r=(1.6-k*.4)*s,tip=[x,y+2.2*s,z];face([[x-r,y,z-r],[x+r,y,z-r],tip],'#497166');face([[x+r,y,z-r],[x+r,y,z+r],tip],'#355f57');face([[x+r,y,z+r],[x-r,y,z+r],tip],'#5c7f66');face([[x-r,y,z+r],[x-r,y,z-r],tip],'#6b8970')}}
function render(){ctx.fillStyle='#b8cdd0';ctx.fillRect(0,0,W,H);faces.length=0;for(let x=-40;x<40;x+=5)for(let z=-40;z<45;z+=5){let road=Math.abs(x+2.5)<5||Math.abs(z+2.5)<4||Math.abs(z+10)<3;face([[x,0,z],[x+5,0,z],[x+5,0,z+5],[x,0,z+5]],road?'#b9b5a0':((x+z)%10===0?'#899d83':'#8ea288'))}for(let i=-26;i<=26;i+=6){tree(i,30);tree(-29,i,.9);tree(29,i,1.1)}for(const p of places){box(p.x,0,p.z,p.w,p.h,p.d,p.color);roof(p);box(p.x,.01,p.z-p.d/2-.7,p.w+1,.18,1.8,'#b3b4a3');box(p.x,0,p.z-p.d/2-.04,1.1,2.2,.12,'#314b4b');for(let xx of [-p.w/3,p.w/3]){box(p.x+xx,1.9,p.z-p.d/2-.06,1.15,1.25,.12,'#d8e3cf');box(p.x+xx,2.46,p.z-p.d/2-.14,1.2,.09,.1,'#607778')}box(p.x+.6,p.h,p.z+1,.7,2,.7,'#8a8271')}
box(0,0,0,3,.5,3,'#9aabac');box(0,.5,0,1.1,6,1.1,'#e0d8bd');box(0,6.5,0,2,1.4,1,'#344e57');box(0,6.65,-.52,1.2,.95,.05,'#e9d9ae');box(0,7,-.58,.08,.6,.03,'#344e57');box(.2,6.82,-.59,.45,.08,.03,'#344e57');
box(player.x,.05,player.z,.65,1.15,.5,'#244a61');box(player.x,1.2,player.z,.5,.5,.48,'#dfbfa1');box(player.x,1.7,player.z,.7,.17,.65,'#334753');
faces.sort((a,b)=>b.z-a.z);for(const f of faces){ctx.beginPath();f.v.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1]));ctx.closePath();ctx.fillStyle=f.c;ctx.fill();ctx.strokeStyle=f.c;ctx.lineWidth=.5;ctx.stroke()}
places.forEach((p,i)=>{let q=screen([p.x,p.h+2.8,p.z]);const el=labels[i];el.style.display=q[2]>1&&q[0]>0&&q[0]<W&&q[1]>90&&q[1]<H-100?'block':'none';el.style.left=q[0]+'px';el.style.top=q[1]+'px';el.textContent=(found.has(p.id)?'✓ ':'')+p.name});}
function tick(t){let dt=Math.min((t-last)/1000,.045);last=t;if(!modal.open){if(!solved)elapsed+=dt;let rot=(keys.has('r')?1:0)-(keys.has('q')?1:0);yaw+=rot*dt*1.4;let f=(keys.has('w')||keys.has('arrowup')?1:0)-(keys.has('s')||keys.has('arrowdown')?1:0),s=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0),len=Math.hypot(f,s)||1;let dx=(Math.sin(yaw)*f+Math.cos(yaw)*s)*dt*7/len,dz=(Math.cos(yaw)*f-Math.sin(yaw)*s)*dt*7/len;if(!blocked(player.x+dx,player.z))player.x+=dx;if(!blocked(player.x,player.z+dz))player.z+=dz;nearest=places.find(p=>Math.hypot(player.x-p.x,player.z-(p.z-p.d/2-1))<5.5)||null;$('#near').textContent=nearest?nearest.name+' — '+nearest.person:'建物の入口に近づいてみよう';$('#interact').disabled=!nearest}render();requestAnimationFrame(tick)}requestAnimationFrame(tick);
